class Solution {
public:
    int minCost(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> dp(n + 1, LLONG_MAX);
        dp[0] = 0;
        for (int r = 1; r <= n; r++) {
            vector<int> freq(n, 0);
            long long trimmed = 0;
            for (int l = r - 1; l >= 0; l--) {
                int x = nums[l];
                if (freq[x] == 0) {
                    // new unique element: not in trimmed yet
                } else if (freq[x] == 1) {
                    trimmed += 2;
                } else {
                    trimmed += 1;
                }
                freq[x]++;
                long long cost = dp[l] + (long long)k + trimmed;
                if (cost < dp[r]) dp[r] = cost;
            }
        }
        return (int)dp[n];
    }
};
